def transform(grid):
    from collections import deque

    h, w = len(grid), len(grid[0])
    bg = max(range(10), key=lambda c: sum(v == c for row in grid for v in row))
    seen = [[False] * w for _ in range(h)]
    comps = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or seen[r][c]:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                            and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        q.append((ny, nx))
            comps.append((color, cells))

    # Find a component with a prominent right-angle corner.
    marker = None
    best = 0
    for color, cells in comps:
        points = set(cells)
        for r, c in cells:
            left = right = up = down = 1
            while (r, c - left) in points:
                left += 1
            while (r, c + right) in points:
                right += 1
            while (r - up, c) in points:
                up += 1
            while (r + down, c) in points:
                down += 1
            horizontal = max(left, right)
            vertical = max(up, down)
            if horizontal >= 3 and vertical >= 3:
                score = horizontal + vertical
                if score > best:
                    best = score
                    marker = (color, r, c, left, right)

    if marker is None:
        return [row[:] for row in grid]

    color, corner_r, corner_c, left, right = marker
    # The marked corner's horizontal arm points one way; select the object
    # lying along the opposite extension of that arm.
    direction = -1 if right > left else 1

    target = None
    best_dist = float("inf")
    for comp_color, cells in comps:
        if comp_color == color:
            continue
        dist = min(
            abs(r - corner_r) +
            (max(0, c - corner_c) if direction == -1 else max(0, corner_c - c))
            for r, c in cells
        )
        if dist < best_dist:
            best_dist = dist
            target = cells

    out = [row[:] for row in grid]
    if target is not None:
        for r, c in target:
            out[r][c] = color
    return out
